/* Twitch Theme - Official Twitch brand colors */

/* Light mode */
[data-theme="twitch-light"] {
  --background: #f6f4f5;
  --foreground: #09090b;
  --card: #ffffff;
  --card-foreground: #09090b;
  --popover: #ffffff;
  --popover-foreground: #09090b;
  --primary: #782ffb;
  --primary-foreground: #ffffff;
  --secondary: #ebeaf5;
  --secondary-foreground: #15151a;
  --muted: #f1edee;
  --muted-foreground: #626369;
  --accent: #6715e1;
  --accent-foreground: #ffffff;
  --destructive: #d40924;
  --destructive-foreground: #ffffff;
  --border: #e1ddde;
  --input: #e8e3e4;
  --ring: #782ffb;
  --chart-1: #782ffb;
  --chart-2: #6715e1;
  --chart-3: #00a3aa;
  --chart-4: #4cb86a;
  --chart-5: #c841a5;
  --radius: 0.5rem;
  --sidebar: #faf8f8;
  --sidebar-foreground: #09090b;
  --sidebar-primary: #782ffb;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #ebeaf5;
  --sidebar-accent-foreground: #15151a;
  --sidebar-border: #e1ddde;
  --sidebar-ring: #782ffb;
  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", monospace;
  --shadow-color: #140033;
  --shadow-opacity: 0.08;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(263 100% 10% / 0.04);
  --shadow-xs: 0 1px 3px 0px hsl(263 100% 10% / 0.06);
  --shadow-sm:
    0 2px 4px 0px hsl(263 100% 10% / 0.08),
    0 1px 2px -1px hsl(263 100% 10% / 0.08);
  --shadow:
    0 2px 4px 0px hsl(263 100% 10% / 0.08),
    0 1px 2px -1px hsl(263 100% 10% / 0.08);
  --shadow-md:
    0 4px 6px 0px hsl(263 100% 10% / 0.1),
    0 2px 4px -1px hsl(263 100% 10% / 0.1);
  --shadow-lg:
    0 8px 10px 0px hsl(263 100% 10% / 0.1),
    0 4px 6px -1px hsl(263 100% 10% / 0.1);
  --shadow-xl:
    0 16px 20px 0px hsl(263 100% 10% / 0.12),
    0 8px 10px -1px hsl(263 100% 10% / 0.12);
  --shadow-2xl: 0 24px 48px 0px hsl(263 100% 10% / 0.2);
  --tracking-normal: -0.01em;
}

/* Dark mode - #0E0E10 is Twitch's signature dark background */
[data-theme="twitch-dark"] {
  --background: #09090b;
  --foreground: #f0eeee;
  --card: #111115;
  --card-foreground: #f0eeee;
  --popover: #16161a;
  --popover-foreground: #f0eeee;
  --primary: #782ffb;
  --primary-foreground: #ffffff;
  --secondary: #1a1a1e;
  --secondary-foreground: #e0ddde;
  --muted: #161619;
  --muted-foreground: #8e8e95;
  --accent: #a491ff;
  --accent-foreground: #09090b;
  --destructive: #de3b3d;
  --destructive-foreground: #ffffff;
  --border: #28282e;
  --input: #1a1a1e;
  --ring: #782ffb;
  --chart-1: #782ffb;
  --chart-2: #a491ff;
  --chart-3: #00b4bb;
  --chart-4: #65c67d;
  --chart-5: #d35bb1;
  --radius: 0.5rem;
  --sidebar: #060607;
  --sidebar-foreground: #f0eeee;
  --sidebar-primary: #782ffb;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #1a1a1e;
  --sidebar-accent-foreground: #e0ddde;
  --sidebar-border: #28282e;
  --sidebar-ring: #782ffb;
  --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.4;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(0 0% 0% / 0.2);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.3);
  --shadow-sm:
    0 2px 4px 0px hsl(0 0% 0% / 0.4), 0 1px 2px -1px hsl(0 0% 0% / 0.4);
  --shadow: 0 2px 4px 0px hsl(0 0% 0% / 0.4), 0 1px 2px -1px hsl(0 0% 0% / 0.4);
  --shadow-md:
    0 4px 6px 0px hsl(0 0% 0% / 0.4), 0 2px 4px -1px hsl(0 0% 0% / 0.4);
  --shadow-lg:
    0 8px 10px 0px hsl(0 0% 0% / 0.4), 0 4px 6px -1px hsl(0 0% 0% / 0.4);
  --shadow-xl:
    0 16px 20px 0px hsl(0 0% 0% / 0.4), 0 8px 10px -1px hsl(0 0% 0% / 0.4);
  --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.5);
}
